item.aggregated_output:
 1	package rollout
 2	
 3	import (
 4		"context"
 5		"encoding/json"
 6		"time"
 7	)
 8	
 9	type Envelope struct {
10		OperationID string    `json:"operation_id"`
11		Deadline    time.Time `json:"deadline"`
12	}
13	
14	type Client interface {
15		Quote(context.Context, Envelope) error
16	}
17	
18	func Quote(parent context.Context, client Client, operationID string) error {
19		const requestBudget = 2 * time.Second
20		deadline := time.Now().Add(requestBudget)
21		encoded, err := json.Marshal(Envelope{OperationID: operationID, Deadline: deadline})
22		if err != nil {
23			return err
24		}
25		var message Envelope
26		if err := json.Unmarshal(encoded, &message); err != nil {
27			return err
28		}
29		for attempt := 0; attempt < 2; attempt++ {
30			if time.Until(message.Deadline) <= 0 {
31				return context.DeadlineExceeded
32			}
33			attemptCtx, cancel := context.WithTimeout(context.Background(), requestBudget)
34			err = client.Quote(attemptCtx, message)
35			cancel()
36			if err == nil {
37				return nil
38			}
39		}
40		return err
41	}
